import { createRouter as createRouterInstance } from "@tanstack/react-router";

// Import the generated route tree (this file will be auto-generated by the Vite plugin)
import { routeTree } from "./routeTree.gen";

export function getRouter() {
  return createRouterInstance({
    routeTree,
    scrollRestoration: true,
  });
}

// Keep a singleton export for compatibility tests and non-Start entrypoints.
export const router = getRouter();

// Register the router instance for type safety
declare module "@tanstack/react-router" {
  interface Register {
    router: ReturnType<typeof getRouter>;
  }
}
